const REQUEST_CHANGE_LABELS={objective:'Engineering objective',quantity:'Quantity',requiredDate:'Required date',priority:'Priority',configuration:'Build configuration',bomRef:'BOM reference',materialOwnership:'Material source',productSafety:'Product-safety relevance',assuranceProfile:'Control level',characterisation:'Requested characterisation',specialCharacteristics:'Special characteristics',batchDataRequirements:'Required batch data',sampleDataRequirements:'Required sample data',photoEvidenceRequirements:'Required photo evidence'};
function friendlyChangeValue(v){if(v===null||v===undefined||v==='')return '—';if(Array.isArray(v))return v.length?v.map(x=>typeof x==='object'?(x.label||x.name||x.id||JSON.stringify(x)):String(x)).join('; '):'None';if(typeof v==='object')return v.label||v.name||v.id||Object.entries(v).map(([k,x])=>`${k}: ${friendlyChangeValue(x)}`).join('; ');if(typeof v==='boolean')return v?'Yes':'No';return String(v)}
