 const items=[['dashboard','Dashboard'],['requests','Prototype Requests'],['action-centre','Action Centre'],['planning','Planning'],['products','Products & BOM'],['process-library','Lab Standards & Resources'],['equipment-master','Resource Assurance'],['serials','Serial History'],['characterisation','Characterisation'],['quality','Quality Workbench'],['reports','Reports'],['admin','Configuration']];
