 items.forEach(([id,label])=>{if(id==='admin'&&role!=='administrator')return;if(id==='quality'&&!quality&&role!=='lab_manager'&&role!=='process_engineer')return;if(id==='planning'&&['engineering_requester','auditor'].includes(role))return; if(id==='products'&&!can('product:view')&&role!=='administrator')return; if(id==='process-library'&&['engineering_requester'].includes(role))return; if(id==='equipment-master'&&!['metrology','lab_manager','administrator','lab_planner','auditor'].includes(role))return; const count=id==='action-centre'?openActions().length:id==='requests'?App.state.requests.filter(r=>r.status!=='CLOSED').length:'';html+=`<button class="nav-link ${App.currentView===id?'active':''}" data-nav="${id}">${label}${count!==''?`<span class="nav-count">${count}</span>`:''}</button>`});
 if(management)html+=`<div class="nav-group-label">Management</div><button class="nav-link ${App.currentView==='management'?'active':''}" data-nav="management">Management KPIs</button>`; if(can('audit:view'))html+=`<div class="nav-group-label">Governance</div><button class="nav-link ${App.currentView==='audit-readiness'?'active':''}" data-nav="audit-readiness">Audit Readiness</button>`;
