function prepareRequestForOpen(r){if(!r)return;try{P.ensurePlanningModel(App.state);P.ensureEnterpriseModel(App.state);r.changeHistory=Array.isArray(r.changeHistory)?r.changeHistory:[];r.overrides=Array.isArray(r.overrides)?r.overrides:[];r.commitmentHistory=Array.isArray(r.commitmentHistory)?r.commitmentHistory:[];P.ensureMaterialRequirements(App.state,r);P.ensureTestRequirements(App.state,r);P.ensureApprovalRecords(App.state,r);P.ensureCapturePlan(App.state,r);P.applyReusePackage(App.state,r,{actor:App.state.identity.name});}catch(e){console.warn('Request open preparation warning',r?.id,e)}}
