function roleDashboardTitle(){const role=currentRole();return ({engineering_requester:'Engineering dashboard',engineering_lead:'Engineering lead dashboard',lab_planner:'Prototype lab dashboard',process_engineer:'Process engineering dashboard',technician:'Technician work queue',quality:'Quality dashboard',metrology:'Measurement readiness dashboard',product_safety:'Product safety dashboard',lab_manager:'Lab management dashboard',approver:'Approval queue',auditor:'Audit overview',administrator:'System administration dashboard'})[role]||'Dashboard'}
function weekBounds(offset=0){const now=new Date(),start=new Date(now);start.setHours(0,0,0,0);const mondayOffset=(start.getDay()+6)%7;start.setDate(start.getDate()-mondayOffset+offset*7);const end=new Date(start);end.setDate(end.getDate()+7);return {start,end};}
