function sumHours(rows){return rows.reduce((n,x)=>n+Number(x.duration||0),0)}
function completedHistoryHours(start,end){return (App.state.buildHistory||[]).filter(h=>inWindow(h.completedAt,start,end)).reduce((n,h)=>n+(h.stepActuals||[]).reduce((a,x)=>a+Number(x.durationHours||0),0)+(h.testActuals||[]).reduce((a,x)=>a+Number(x.durationHours||0),0),0)}
function groupOperational(rows,keyFn,labelFn){const m=new Map();for(const x of rows){const k=keyFn(x)||'Unassigned',e=m.get(k)||{key:k,label:labelFn?labelFn(x,k):k,hours:0,count:0};e.hours+=Number(x.duration||0);e.count++;m.set(k,e)}return [...m.values()].sort((a,b)=>b.hours-a.hours)}
function opsLoadBars(rows,empty='No scheduled work in this period.'){if(!rows.length)return `<div class="empty compact">${esc(empty)}</div>`;const max=Math.max(...rows.map(x=>x.hours),1);return `<div class="ops-load-bars">${rows.slice(0,7).map(x=>`<div class="ops-load-row"><div><strong>${esc(x.label)}</strong><small>${x.count} task${x.count===1?'':'s'}</small></div><div class="ops-load-track"><span style="width:${Math.min(100,100*x.hours/max).toFixed(1)}%"></span></div><b>${x.hours.toFixed(1)} h</b></div>`).join('')}</div>`}
function operationalWeekBoard(rows,bounds){const days=Array.from({length:7},(_,i)=>{const d=new Date(bounds.start);d.setDate(d.getDate()+i);return d});return `<div class="ops-week-board">${days.map(d=>{const next=new Date(d);next.setDate(next.getDate()+1);const items=rows.filter(x=>inWindow(x.start,d,next)).sort((a,b)=>new Date(a.start)-new Date(b.start));return `<div class="ops-day ${d.toDateString()===new Date().toDateString()?'today':''}"><div class="ops-day-head"><strong>${d.toLocaleDateString(undefined,{weekday:'short'})}</strong><span>${d.getDate()}</span></div><div class="ops-day-body">${items.slice(0,5).map(x=>`<button type="button" class="ops-job" data-open-request="${esc(x.requestId)}"><span>${new Date(x.start).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})}</span><strong>${esc(x.requestId)}</strong><small>${esc(x.name)}</small><em>${Number(x.duration).toFixed(1)} h · ${esc(x.person)}</em></button>`).join('')||'<span class="ops-free">No scheduled work</span>'}${items.length>5?`<small class="ops-more">+${items.length-5} more</small>`:''}</div></div>`}).join('')}</div>`}
