async function guidedReleaseDevelopment(actionId,devId){try{const newId=new P.ProcessService(App.state).releaseDevelopment(devId),dev=App.state.processDevelopments.find(d=>d.id===devId),route=App.state.routes.find(r=>r.requestId===dev.requestId),step=route?.steps.find(s=>s.type!=='standard'&&(s.processId===dev.libraryCandidate||String(dev.name).includes(s.name.split(' — ')[0])));if(step){const proc=App.state.processes.find(p=>p.id===newId);step.processId=newId;step.processRevision='A';step.type='standard';step.readiness='pending';step.name=proc.name}App.state.actions=(App.state.actions||[]).filter(a=>a.id!==actionId);P.audit(App.state,'Action Centre blocker cleared','Action',actionId,'Open','Resolved',`Process released as ${newId}`);await persist();render();toast(`Blocker cleared. Process released as ${newId} Rev A.`)}catch(e){toast(e.message,true);resolveActionModal(actionId)}}

function renderActionCentre(){
 const mode=App.filters.actionGroup||'severity', proposals=new P.ImprovementService().generate(App.state), items=[...openActions()];
 const groupOf=a=>mode==='build'?(a.requestId||'General'):mode==='owner'?(a.owner||'Unassigned'):mode==='function'?(a.category||'General'):(a.severity==='bad'?'Critical / release risk':a.severity==='warn'?'Attention':'Routine');
 const groups={};items.forEach(a=>(groups[groupOf(a)]||(groups[groupOf(a)]=[])).push(a));
 const controls=`<div class="filter-row"><button class="filter-chip ${mode==='severity'?'active':''}" data-action-group="severity">Severity</button><button class="filter-chip ${mode==='build'?'active':''}" data-action-group="build">Build</button><button class="filter-chip ${mode==='owner'?'active':''}" data-action-group="owner">Person</button><button class="filter-chip ${mode==='function'?'active':''}" data-action-group="function">Function</button></div>`;
 const queue=Object.entries(groups).sort((a,b)=>b[1].length-a[1].length).map(([g,arr])=>`<div class="card"><div class="section-title-row"><h2>${esc(g)}</h2><span class="pill">${arr.length}</span></div>${arr.map(actionItem).join('')}</div>`).join('');
 const imp=`<div class="card"><div class="section-title-row"><div><span class="eyebrow">CONTINUOUS IMPROVEMENT</span><h2>Actionable improvement proposals</h2><div class="subtle">Generated from current bookings, qualification coverage, calibration dates, actual process durations and recurring build issues.</div></div><span class="pill">${proposals.length}</span></div>${proposals.slice(0,8).map(x=>`<div class="action-item"><div class="action-stripe ${x.severity==='High'?'bad':'warn'}"></div><div><h3>${esc(x.title)}</h3><div class="subtle"><strong>${esc(x.type)}</strong> · owner ${esc(x.owner)}</div><div class="action-meta"><span>Evidence: ${esc(x.why)}</span><span>Proposal: ${esc(x.proposal)}</span><span>Impact: ${esc(x.impact)}</span></div></div><div>${btn('Review →',`data-improvement="${esc(x.id)}"`,'button small primary')}</div></div>`).join('')||'<div class="empty">No material improvement proposal identified.</div>'}</div>`;
 return pageHeader('Action Centre','A single prioritised work queue. Group it by severity, build, owner or function; improvement proposals are kept separate from mandatory build actions.')+controls+`<div class="grid cols-2">${queue}</div><div style="height:14px"></div>${imp}`;
}
function roleLabel(roleId){return P.ROLES.find(x=>x.id===roleId)?.label||roleId}
function userForRole(roleId){return App.state.users.find(u=>u.role===roleId)}
function gateAtOrBeyond(r,gate){return P.GATES.indexOf(r.currentGate)>=P.GATES.indexOf(gate)}
function readinessCheck(rs,name){return rs.checks.find(c=>c[0]===name)}
function canEditRequest(r){return currentRole()==='administrator'||currentRole()==='engineering_requester'||currentRole()==='engineering_lead'}
function samplesForRequest(requestId){return (App.state.serials||[]).filter(s=>s.requestId===requestId&&s.status!=='Cancelled').sort((a,b)=>String(a.sampleNumber||a.serial).localeCompare(String(b.sampleNumber||b.serial),undefined,{numeric:true}))}
function sampleLabel(s){if(!s)return 'Build-level';return `Sample ${s.sampleNumber||'—'} · ${s.sampleId||s.serial}${s.serialNumber?` · SN ${s.serialNumber}`:''}`}
function sampleByRef(requestId,ref){return samplesForRequest(requestId).find(s=>s.serial===ref||s.sampleId===ref||s.sampleNumber===ref||s.serialNumber===ref)}
function stepDoneForSample(step,sample){return !!sample?.processHistory?.some(h=>h.stepId===step.id)}
function activeSamplesForRequest(r){return samplesForRequest(r.id).filter(s=>!['Scrapped','Cancelled'].includes(s.status))}
function executionCompleteForRequest(r){const route=App.state.routes.find(x=>x.requestId===r.id),samples=activeSamplesForRequest(r);if(!route?.steps?.length||samples.length<Number(r.quantity||0))return false;return route.steps.filter(s=>!s.optional).every(step=>samples.every(sample=>stepDoneForSample(step,sample)))}
function currentExecutionStep(r){const route=App.state.routes.find(x=>x.requestId===r.id),samples=activeSamplesForRequest(r);if(!route?.steps?.length)return null;return route.steps.filter(s=>!s.optional).find(step=>samples.length===0||samples.some(sample=>!stepDoneForSample(step,sample)))||null}
function processDefinitionForStep(step){const live=App.state.processes.find(p=>p.id===step?.processId);if(!live)return null;if(!step?.processRevision||String(live.revision)===String(step.processRevision))return live;const hist=(live.revisionHistory||[]).find(h=>String(h.rev||h.revision)===String(step.processRevision)&&h.snapshot);return hist?.snapshot||live}
function processCapabilityForStep(r,step){const proc=processDefinitionForStep(step),booking=(App.state.bookings||[]).find(b=>b.requestId===r.id&&b.stepId===step?.id);return proc?.equipmentCapability||booking?.equipmentCapability||null}
function cpCharacteristicsForStep(r,step){const cp=App.state.controlPlans.find(c=>c.id===r.controlPlanId);if(!cp||!step)return[];const procNo=Number(String(step.processId||'').match(/(\d+)$/)?.[1]||NaN);return (cp.characteristics||[]).filter(c=>c.processStepId===step.id||c.processId===step.processId||(!c.processStepId&&!c.processId&&(Number(c.processStep)===Number(step.order)||Number(c.processStep)===procNo)))}
function cpCharacteristicNeedsEachSample(c){return /100%|each\s*unit|1\s*\/\s*unit|per\s*unit/i.test(`${c?.sampleSize||''} ${c?.frequency||''}`)}
function stableSampleOrder(samples){return (samples||[]).slice().sort((a,b)=>Number(a.sampleNumber||0)-Number(b.sampleNumber||0)||String(a.sampleId||a.serial||'').localeCompare(String(b.sampleId||b.serial||'')))}
function evenlySpacedSamples(samples,count){const a=stableSampleOrder(samples),n=a.length,k=Math.max(0,Math.min(n,Math.round(Number(count)||0)));if(!k)return[];if(k>=n)return a;if(k===1)return[a[0]];const out=[],seen=new Set();for(let i=0;i<k;i++){let idx=Math.round(i*(n-1)/(k-1));while(seen.has(idx)&&idx<n-1)idx++;seen.add(idx);out.push(a[idx])}return out}
function cpSamplingPlan(r,step,c,samples=activeSamplesForRequest(r)){
 const all=stableSampleOrder(samples),n=all.length,raw=`${c?.sampleSize||''} ${c?.frequency||''}`.trim(),txt=raw.toLowerCase();let chosen=[],label=raw||'1 sample';
 if(!n)return {refs:[],samples:[],count:0,total:0,label};
 if(cpCharacteristicNeedsEachSample(c)){chosen=all;label='100% · every sample'}
 else if(/first\s*(?:&|and|\/)?\s*last/.test(txt)){chosen=[all[0],all[n-1]].filter((x,i,a)=>x&&a.indexOf(x)===i);label='First + last sample'}
 else {const pct=txt.match(/(\d+(?:\.\d+)?)\s*%/),per=txt.match(/1\s*(?:\/|per)\s*(\d+)/i),num=String(c?.sampleSize||'').match(/(^|\D)(\d+)(?:\s*(?:pcs|pieces|samples?|\/batch|per\s*batch|\/lot|per\s*lot))?/i);let count=0;if(pct)count=Math.max(1,Math.ceil(n*Number(pct[1])/100));else if(per)count=Math.max(1,Math.ceil(n/Number(per[1])));else if(num)count=Math.max(1,Number(num[2]));else if(/batch|lot|shift|start[- ]?up/.test(txt))count=1;else count=1;chosen=evenlySpacedSamples(all,count);label=raw||`${chosen.length} sample${chosen.length===1?'':'s'}`}
 return {refs:chosen.map(x=>x.serial),samples:chosen,count:chosen.length,total:n,label};
}
function cpSampleRequired(r,step,c,sample,samples=activeSamplesForRequest(r)){return cpSamplingPlan(r,step,c,samples).refs.includes(sample?.serial)}
function processWorkInstructionSteps(proc,step){const wi=proc?.workInstruction;if(Array.isArray(wi))return wi.map(String).filter(Boolean);if(Array.isArray(wi?.steps))return wi.steps.map(String).filter(Boolean);if(typeof wi==='string'&&wi.trim())return [wi.trim()];if(Array.isArray(step?.workInstruction))return step.workInstruction.map(String).filter(Boolean);if(typeof step?.instruction==='string'&&step.instruction.trim())return[step.instruction.trim()];return [`Execute ${step?.name||'this operation'} using the approved method.`]}
function processRecipeSummary(proc,step){const params=(Array.isArray(step?.processDataFields)&&step.processDataFields.length?step.processDataFields:(proc?.params||[])).filter(x=>{const cls=String(x?.dataClass||x?.category||'').toLowerCase(),level=String(x?.captureLevel||x?.scope||'batch').toLowerCase();return ['machine','setup','recipe'].includes(cls)||level==='batch'});return params}

function measurementKind(r,m){const cp=App.state.controlPlans.find(c=>c.id===r.controlPlanId),ids=new Set((cp?.characteristics||[]).map(c=>c.id));return m.measurementType||(ids.has(m.characteristicId)?'control-plan':'end-characterisation')}
