function downloadBatchEvidenceTemplate(requestId){const r=requestById(requestId);P.syncRequestFlowdown(App.state,r);const defs=r.sampleDataRequirements||[],samples=samplesForRequest(requestId),quote=v=>`"${String(v??'').replaceAll('"','""')}"`,header=['sample_number','lab_sample_id','serial_number',...defs.map(d=>d.label+(d.unit?` [${d.unit}]`:''))],rows=samples.map(sm=>{P.ensureSampleCaptureFields(sm,r);return [sm.sampleNumber,sm.sampleId||sm.serial,sm.serialNumber||'',...defs.map(d=>sm.dataFields.find(x=>x.definitionId===d.id)?.value||'')];});downloadTextFile(`batch_evidence_${requestId}.csv`,[header,...rows].map(row=>row.map(quote).join(',')).join('\n'),'text/csv')}
function importBatchEvidenceCsv(requestId){const r=requestById(requestId);P.syncRequestFlowdown(App.state,r);const input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;const rows=parseCsv(await file.text());if(rows.length<2){toast('CSV has no sample rows.',true);return}const headers=rows[0].map(x=>String(x).trim()),norm=x=>String(x||'').toLowerCase().replace(/\s*\[[^\]]*\]\s*$/,'').trim(),defs=r.sampleDataRequirements||[],sampleIdxs=headers.map((h,i)=>['sample_number','sample','lab_sample_id','serial_number'].includes(norm(h).replaceAll(' ','_'))?i:-1).filter(i=>i>=0);if(!sampleIdxs.length){toast('CSV needs sample_number, lab_sample_id or serial_number.',true);return}let updated=0,skipped=0;for(const vals of rows.slice(1)){const ref=sampleIdxs.map(i=>String(vals[i]??'').trim()).find(Boolean)||'',sm=sampleByRef(requestId,ref);if(!sm){skipped++;continue}P.ensureSampleCaptureFields(sm,r);for(const d of defs){const idx=headers.findIndex(h=>norm(h)===norm(d.label));if(idx<0)continue;const row=sm.dataFields.find(x=>x.definitionId===d.id);if(row){row.value=String(vals[idx]??'').trim();updated++;}}}P.invalidateBuildReport(App.state,r,'Batch evidence CSV imported');P.audit(App.state,'Batch evidence CSV imported','Request',r.id,'—',`${updated} field value(s)`,`${file.name}; ${skipped} unresolved sample row(s)`);await persist();closeModal();render();toast(`Imported ${updated} sample field value(s)${skipped?`; ${skipped} sample row(s) skipped`:''}.`,skipped>0)}catch(e){toast(`Batch evidence import failed: ${e.message}`,true)}};input.click()}
function photoMatrixModal(requestId){const r=requestById(requestId);P.syncRequestFlowdown(App.state,r);const slots=r.photoEvidenceRequirements||[],samples=samplesForRequest(requestId);const body=slots.length&&samples.length?`<div class="table-wrap photo-matrix-wrap"><table class="data-table"><thead><tr><th>Sample</th>${slots.map(s=>`<th>${esc(s.label)}${s.required!==false?' *':''}</th>`).join('')}</tr></thead><tbody>${samples.map(sm=>`<tr><th>${esc(sm.sampleNumber||'—')}<small>${esc(sm.serialNumber||sm.sampleId||sm.serial)}</small></th>${slots.map(slot=>{const ph=(sm.evidencePhotos||[]).find(x=>x.slotId===slot.id&&x.dataUrl);return `<td class="photo-slot-cell ${ph?'complete':''}">${ph?'<span class="photo-slot-mark">✓</span>':'<span class="photo-slot-mark missing">●</span>'}${btn(ph?'Replace':'Add',`data-photo-slot="${sm.serial}|${slot.id}"`,'button tiny secondary')}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">Define photo evidence slots on the request and create the sample register first.</div>';openModal(`Batch photo matrix · ${r.id}`,`<div class="callout"><h3>Consistent photo evidence</h3><p>Every sample uses the same controlled photo slots. A missing required photo is visible immediately.</p></div>${body}`,btn('Close','data-modal-close','button'),true);setTimeout(()=>{$$('[data-photo-slot]').forEach(el=>el.onclick=()=>{const [sampleRef,slotId]=el.dataset.photoSlot.split('|');closeModal();photoSlotModal(requestId,sampleRef,slotId)})},0)}
