 const eqField=capability?`<div class="field"><label>Equipment · ${esc(capability)}</label><select id="execEquipment">${readyEq.map(e=>`<option value="${e.id}" ${(run?.equipmentId||planned?.equipmentId||selected.equipmentId)===e.id?'selected':''}>${esc(e.name)} · ${esc(e.id)}</option>`).join('')}</select>${readyEq.length?'':`<small class="bad-text">No ready equipment with capability ${esc(capability)}.</small>`}</div>`:`<div class="field"><label>Equipment</label><select id="execEquipment"><option value="">No equipment required</option>${readyEq.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.id)}</option>`).join('')}</select></div>`;
 let action='';if(!can('execution:run'))action='<div class="callout warn"><strong>Prototype Technician action required</strong></div>';else if(run&&!reqStatus.complete)action=btn(`Record required data · ${reqStatus.missing.length} missing`, `data-process-data="${r.id}|${selected.id}"`,'button primary');else if(run)action=btn('Complete this execution',`data-complete-step="${selected.id}"`,'button primary');else if(!pending.length)action='<span class="status good">✓ Step complete</span>';else if(!isCurrent)action=`<div class="callout warn"><strong>Complete ${esc(routeCurrent?.name)} first.</strong></div>`;else if(!readyEq.length&&capability)action='<div class="callout warn"><strong>Ready equipment required before starting.</strong></div>';else action=btn('Start operation', `data-start-step="${selected.id}"`,'button primary');
 const history=(selected.executionRuns||[]).length?`<details class="help-task"><summary>Execution history · ${(selected.executionRuns||[]).length}</summary><div class="help-body">${selected.executionRuns.map(x=>`<div class="score-row"><span>${P.formatDateTime(x.startedAt)} · ${(x.sampleIds||[]).length} sample(s)</span><strong>${esc(x.status)}${x.actualDurationHours?` · ${Number(x.actualDurationHours).toFixed(2)} h`:''}</strong></div>`).join('')}</div></details>`:'';
