function workspaceQuality(r){const ds=App.state.deviations.filter(d=>d.requestId===r.id);return `<div class="card"><div class="section-title-row"><div><h2>Quality / deviation / rework</h2><div class="subtle">Issues remain connected to build, serial, step and measurement.</div></div>${can('quality:disposition')?btn('+ New issue','data-new-deviation','button small primary'):''}</div>${ds.length?ds.map(d=>`<div class="callout ${d.releaseHold?'bad':'warn'}" style="margin-bottom:10px"><h3>${esc(d.id)} · ${esc(d.type)} · ${esc(d.status)}</h3><p><strong>Sample:</strong> ${esc(sampleDisplayFromRef(r.id,d.serial))} · <strong>Step:</strong> ${esc(d.step)}</p><p style="margin-top:6px"><strong>Detected:</strong> ${esc(d.measurement)}</p><p style="margin-top:6px"><strong>Contain:</strong> ${esc(d.containment)}</p><p style="margin-top:6px"><strong>Disposition:</strong> ${esc(d.disposition)}</p><p style="margin-top:6px"><strong>Release hold:</strong> ${d.releaseHold?'YES':'No'}</p>${d.status!=='CLOSED'&&can('quality:disposition')?`<div style="margin-top:10px">${btn('Open disposition →',`data-disposition="${d.id}"`,'button small primary')}</div>`:''}</div>`).join(''):'<div class="empty">No quality issues linked to this request.</div>'}</div>`}
