 const r=cp.buildSpecific?requestById(cp.buildRequestId):null;
 if(cp.buildSpecific&&r&&!P.buildChangeApprovalsComplete(App.state,r,'Control Plan'))return {canApprove:false,reason:'Complete the build-specific Process Engineering / Quality review first.',stage:'delta'};
 const invalid=(cp.characteristics||[]).filter(c=>c.classification&&!P.controlCharacteristicReady(c));
 if(invalid.length)return {canApprove:false,reason:`Complete the controlled definition for ${invalid.map(c=>c.characteristic||c.id).join(', ')} first.`,stage:'definition',invalidCharacteristicIds:invalid.map(c=>c.id)};
