function workspaceApprovals(r,controlOnly=false){P.ensureApprovalRecords(App.state,r);let a=App.state.approvals.filter(x=>x.requestId===r.id);a=controlOnly?a.filter(x=>x.type==='Product Safety'):a.filter(x=>x.stage==='release'||(!x.stage&&x.type!=='Product Safety'&&x.type!=='Build Report Approval'));const releaseAction=!controlOnly&&(can('release:review')||can('release:approve'))&&['QUALITY REVIEW','ENGINEERING REVIEW','RELEASE APPROVAL','BUILD READINESS REVIEW','READY TO BUILD'].includes(r.status)?btn('Run final release check',`data-release-request="${r.id}"`,'button primary'):'';return `<div class="card"><div class="section-title-row"><div><span class="eyebrow">${controlOnly?'SPECIAL / SAFETY APPROVALS':'RELEASE APPROVALS'}</span><h2>${controlOnly?'Applicable controlled approvals':'Required release sign-offs'}</h2></div><div>${releaseAction}</div></div>${a.length?a.map(x=>`<div class="action-item"><div class="action-stripe ${x.status==='Approved'?'good':'warn'}"></div><div><h3>${esc(x.type)}</h3><div class="subtle">Required role: ${esc(x.role)} · Assigned: ${esc(x.person)}</div><div class="action-meta"><span>${x.timestamp?P.formatDateTime(x.timestamp):'Pending'}</span><span>${esc(x.comment||'')}</span></div></div><div>${x.status==='Pending'&&canApproveRecord(x)?btn('Approve',`data-approve-record="${x.id}"`,'button small primary'):x.status==='Pending'&&currentRole()!=='administrator'?btn(`Switch to ${x.person} →`,`data-switch-role="${roleIdForLabel(x.role)}"`,'button small secondary'):status(x.status)}</div></div>`).join(''):`<div class="callout"><h3>${controlOnly?'No special approval required':'No additional release approval configured'}</h3><p>${controlOnly?'This request is not configured for a separate product-safety/readiness approval.':'Release will still enforce Control Plan approval, quality disposition and release-hold rules.'}</p></div>`}</div>`}
