function workspaceCost(r){const c=new P.CostService().estimate(App.state,r.id);r.costEstimate=Number(c.total.toFixed(2));const rows=[['Materials',c.material],['Labour',c.labour],['Equipment',c.equipment],['Process charges',c.process],['Standard tests',c.tests],['Consumables',c.consumables],['Process / test development',c.development],['External services',c.external],['Contingency',c.contingency]];return `<div class="card"><div class="section-title-row"><div><h2>Prototype cost</h2><div class="subtle">Resource plan + BOM + optional consumables + controlled finance rates.</div></div><div class="route-toolbar">${btn(r.consumablesEnabled?'Consumables on':'Consumables optional',`data-configure-consumables="${r.id}"`,'button small secondary')}${btn('Cost master →','data-nav="process-library"','button small secondary')}</div></div><div class="grid cols-3">${metric('Estimate',P.currency(c.total))+metric('Consumables',P.currency(c.consumables),r.consumablesEnabled?'BOM + build + process/test':'Only process/test defaults')+metric('Actual',r.costActual?P.currency(r.costActual):'Open')}</div><div style="height:12px"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Category</th><th>Estimate</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x[0])}</td><td>${P.currency(x[1])}</td></tr>`).join('')}</tbody></table></div>${c.consumableLines?.length?`<details class="planning-details"><summary>Consumable detail · ${c.consumableLines.length} line(s)</summary><div class="table-wrap"><table class="data-table"><thead><tr><th>Source</th><th>Consumable</th><th>Qty</th><th>Cost</th></tr></thead><tbody>${c.consumableLines.map(x=>`<tr><td>${esc(x.source)}</td><td>${esc(x.description)}</td><td>${Number(x.qty).toFixed(2)} ${esc(x.unit)}</td><td>${P.currency(x.cost)}</td></tr>`).join('')}</tbody></table></div></details>`:''}</div>`}
function configureConsumablesModal(requestId){const r=requestById(requestId),product=App.state.products.find(p=>p.id===r.productId),bom=(product?.bom||[]).filter(x=>String(x.kind||'component').toLowerCase()==='consumable'),existing=r.buildConsumables||[],byBom=new Map(existing.filter(x=>x.bomItemId).map(x=>[x.bomItemId,x]));let draft=[...bom.map(x=>({...P.deepClone(x),id:byBom.get(x.id)?.id||P.uid('CONS'),bomItemId:x.id,description:byBom.get(x.id)?.description||x.description,qty:byBom.get(x.id)?.qty??x.qtyPerUnit,basis:byBom.get(x.id)?.basis||x.basis||'unit',unitCost:byBom.get(x.id)?.unitCost??x.unitCost,wastePct:byBom.get(x.id)?.wastePct??x.wastePct})),...existing.filter(x=>!x.bomItemId).map(P.deepClone)];const redraw=()=>{const body=$('#consumableRows');if(!body)return;body.innerHTML=draft.map((x,i)=>`<tr><td><strong>${esc(x.bomItemId?'BOM':'Build')}</strong></td><td><input data-cons-desc="${i}" value="${esc(x.description||'')}"></td><td><input data-cons-qty="${i}" type="number" step="any" min="0" value="${Number(x.qty??x.qtyPerUnit??0)}"></td><td><select data-cons-basis="${i}"><option value="unit" ${x.basis==='unit'?'selected':''}>per unit</option><option value="build" ${x.basis==='build'?'selected':''}>per build</option></select></td><td><input data-cons-unit="${i}" value="${esc(x.unit||'pcs')}"></td><td><input data-cons-cost="${i}" type="number" step="any" min="0" value="${Number(x.unitCost||0)}"></td><td><input data-cons-waste="${i}" type="number" step="any" min="0" value="${Number(x.wastePct||0)}"></td><td>${x.bomItemId?'Inherited':btn('Remove',`data-remove-cons="${i}"`,'button tiny danger')}</td></tr>`).join('');$$('[data-remove-cons]').forEach(el=>el.onclick=()=>{collect();draft.splice(Number(el.dataset.removeCons),1);redraw()})};const collect=()=>{draft.forEach((x,i)=>{const q=$(`[data-cons-qty="${i}"]`);if(!q)return;x.description=$(`[data-cons-desc="${i}"]`).value.trim();x.qty=Number(q.value||0);x.basis=$(`[data-cons-basis="${i}"]`).value;x.unit=$(`[data-cons-unit="${i}"]`).value.trim()||'pcs';x.unitCost=Number($(`[data-cons-cost="${i}"]`).value||0);x.wastePct=Number($(`[data-cons-waste="${i}"]`).value||0)})};openModal('Consumables & build costing',`<div class="callout"><h3>Optional by design</h3><p>Enable only when useful. Product-BOM consumables are inherited per unit; add one-off build consumables separately. Nothing here is required to release a build.</p></div><label class="plan-switch" style="margin:12px 0"><input id="consEnabled" type="checkbox" ${r.consumablesEnabled?'checked':''}><span>Track BOM/build consumables and include their cost</span></label><div class="table-wrap"><table class="data-table"><thead><tr><th>Source</th><th>Consumable</th><th>Qty</th><th>Basis</th><th>Unit</th><th>€/unit</th><th>Waste %</th><th></th></tr></thead><tbody id="consumableRows"></tbody></table></div><div style="margin-top:10px">${btn('+ Build consumable','data-add-consumable','button small secondary')}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save consumables','data-save-consumables','button primary')}`,true);setTimeout(()=>{redraw();$('[data-add-consumable]').onclick=()=>{collect();draft.push({id:P.uid('CONS'),description:'',qty:1,basis:'build',unit:'pcs',unitCost:0,wastePct:0});redraw()};$('[data-save-consumables]').onclick=async()=>{collect();r.consumablesEnabled=$('#consEnabled').checked;r.buildConsumables=draft.map(x=>({id:x.id||P.uid('CONS'),...(x.bomItemId?{bomItemId:x.bomItemId}:{}),description:x.description,qty:x.qty,basis:x.basis,unit:x.unit,unitCost:x.unitCost,wastePct:x.wastePct}));const c=new P.CostService().estimate(App.state,r.id);r.costEstimate=Number(c.total.toFixed(2));P.audit(App.state,'Consumable costing updated','Request',r.id,'Previous consumable plan',`${r.buildConsumables.length} line(s)`,r.consumablesEnabled?'Enabled':'Disabled');await persist();closeModal();render();toast('Consumable plan and cost roll-up updated.')}},0)}
