function workspaceCloseout(r){const canClose=['DELIVERED'].includes(r.status)&&(can('triage')||can('release:approve')||currentRole()==='administrator');return `<div class="section-stack">${workspaceDelivery(r)}${currentRole()==='administrator'?`<div class="card"><div class="section-title-row"><div><span class="eyebrow">BUILD DATA & FILES</span><h2>Download underlying build evidence</h2><div class="subtle">Export individual CSV datasets, process-step worksheets and linked photographs independently of the Build Report.</div></div>${btn('Open data & files',`data-build-files="${r.id}"`,'button primary')}</div></div>`:''}${canClose?`<div class="card"><div class="section-title-row"><div><span class="eyebrow">CLOSEOUT</span><h2>Close controlled prototype record</h2><div class="subtle">Close only after handover is acknowledged and the audit/evidence package is retained.</div></div>${btn('Close request',`data-close-request="${r.id}"`,'button primary')}</div></div>`:''}<details class="help-task"><summary>Cost, documents, audit trail & lessons</summary><div class="help-body">${workspaceRecords(r)}</div></details></div>`}

