function auditRule(status,severity,clause,title,evidence,action,area){const key=String(`${area}-${title}`).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');return {key,status,severity,clause,title,evidence,action,area}}
