 const f=framework==='iso17025'?'iso17025':'iatf',rules=[],auditProfile=App.state.settings?.auditProfile||{},active=(App.state.requests||[]).filter(r=>!['CLOSED'].includes(r.status)),formal=active.filter(r=>P.ensureAssuranceProfile(r).formalLevel>=2),usedProcessIds=new Set((App.state.routes||[]).filter(rt=>active.some(r=>r.id===rt.requestId)).flatMap(rt=>(rt.steps||[]).map(s=>s.processId).filter(Boolean))),usedProcesses=(App.state.processes||[]).filter(p=>usedProcessIds.has(p.id)),expiredEq=(App.state.equipment||[]).filter(e=>e.calibrationRequired!==false&&(!P.validCalibrationCertificate(App.state,e.id,P.todayISO())||e.calibrationStatus!=='Valid'||(e.calibrationDue&&e.calibrationDue<P.todayISO()))),overdueMaint=(App.state.equipment||[]).filter(e=>e.maintenanceDue&&e.maintenanceDue<P.todayISO()),scopeMissing=auditScopeRows().filter(x=>!x.activity||!x.range||!x.method),invalidMeas=(App.state.measurements||[]).filter(m=>m.calibrationRequired&&m.equipmentCalibrationStatus!=='Valid'),openHolds=(App.state.deviations||[]).filter(d=>d.releaseHold&&d.status!=='CLOSED'),unreleased=usedProcesses.filter(p=>p.status!=='Released'||!p.workInstruction?.steps?.length||p.workInstruction?.status!=='Released'),cpBad=formal.filter(r=>{const cp=(App.state.controlPlans||[]).find(c=>c.id===r.controlPlanId);return !cp||cp.status!=='Approved'}),scMissing=formal.filter(r=>(r.specialCharacteristics||[]).length).filter(r=>{const cp=(App.state.controlPlans||[]).find(c=>c.id===r.controlPlanId);return !cp||(cp.characteristics||[]).filter(c=>c.classification).some(c=>!P.controlCharacteristicReady(c))}),closed=(App.state.requests||[]).filter(r=>r.status==='CLOSED'),unapprovedReports=closed.filter(r=>P.ensureBuildReportApproval(App.state,r).status!=='Approved'),certs=(App.state.trainingCertificates||[]),expiredCerts=certs.filter(c=>c.status==='Valid'&&c.expiresAt&&c.expiresAt<P.todayISO()),missingEvidence=(App.state.measurements||[]).filter(m=>!m.evidence),auditCount=(App.state.auditTrail||[]).length