  const internalAuditReady=!!String(auditProfile.internalAuditReference||'').trim();
  rules.push(auditRule(internalAuditReady?'Ready':'Minor','Minor','8.8','Internal-audit programme / record is referenced',internalAuditReady?`Controlled internal-audit reference: ${auditProfile.internalAuditReference}`:'No controlled internal-audit programme / report reference is recorded','Record the controlled internal-audit programme or latest audit-report reference','Internal audit'));
