function auditFindingTargets(rule){const area=String(rule.area||'').toLowerCase();if(area==='audit scope')return {label:'Define scope',action:'audit-profile'};if(area==='audit trail'||area==='internal audit')return {label:'Add controlled reference',action:'audit-profile'};if(area==='maintenance state'||/maintenance state/.test(String(rule.title||'').toLowerCase()))return {label:'Schedule maintenance',action:'maintenance'};if(/laboratory scope|measurement uncertainty/.test(area))return {label:'Complete equipment scope',action:'scope-equipment'};if(/measurement resources|^equipment$/.test(area))return {label:'Resolve calibration',action:'calibration'};if(/competence|personnel/.test(area))return {label:'Schedule training',action:'training'};if(/standardized work|methods/.test(area))return {label:'Open affected method',action:'process-library'};if(/control plan|special characteristics/.test(area))return {label:'Open affected build',action:'controls'};if(/measurement traceability|metrological traceability|technical records/.test(area))return {label:'Open affected evidence',action:'affected-evidence'};if(/corrective action|validity of results/.test(area))return {label:'Resolve quality hold',action:'quality'};if(/documented information|reporting/.test(area))return {label:'Open Build Reports',action:'reports'};if(/audit trail|internal audit/.test(area))return {label:'Open audit evidence pack',action:'audit-pack'};return {label:'Open evidence pack',action:'audit-pack'}}
