function renderAuditReadiness(){if(!can('audit:view')&&currentRole()!=='administrator')return pageHeader('Audit Readiness','Audit access required.')+'<div class="empty">Auditor, Quality, Lab Manager or Administrator access is required.</div>';const framework=App.filters.auditFramework||'iatf',a=auditAssessment(framework),scope=auditScopeRows(),profile=App.state.settings?.auditProfile||{},open=a.rules.filter(x=>x.status!=='Ready'),ready=a.rules.filter(x=>x.status==='Ready'),scoreClass=a.major?'bad':a.minor?'warn':'good';return pageHeader('Audit Readiness','Fix evidence gaps through guided actions.',`${btn('Audit evidence pack','data-audit-pack','button primary')}`)+`<div class="card audit-framework-card"><div class="section-title-row"><div><span class="eyebrow">AUDIT SCOPE</span><h2>${esc(profile.scopeStatement||'Scope not defined')}</h2><div class="subtle">${profile.organisation?esc(profile.organisation):'Organisation required'}${profile.site?' · '+esc(profile.site):' · Site/lab required'}</div></div>${btn(profile.scopeStatement?'Edit scope':'Define scope','data-audit-profile','button small primary')}</div><div class="audit-score-grid"><div class="audit-score ${scoreClass}"><span>Readiness</span><strong>${a.score}%</strong></div><div class="audit-count major"><strong>${a.major}</strong><span>Major</span></div><div class="audit-count minor"><strong>${a.minor}</strong><span>Minor</span></div><div class="audit-count ready"><strong>${a.ready}</strong><span>Ready</span></div></div><label class="compact-select">Framework<select id="auditFramework"><option value="iatf" ${framework==='iatf'?'selected':''}>IATF 16949</option><option value="iso17025" ${framework==='iso17025'?'selected':''}>ISO/IEC 17025</option></select></label></div><div class="card"><div class="section-title-row"><div><span class="eyebrow">OPEN FINDINGS</span><h2>${open.length?`${open.length} item${open.length===1?'':'s'} to resolve`:'No open automated evidence gaps'}</h2></div></div><div class="audit-guided-list">${open.map(x=>`<div class="audit-guided-row"><div>${auditSeverityPill(x.status)}<strong>${esc(x.area)} · ${esc(x.title)}</strong><small>${esc(x.evidence)}</small></div>${btn('Resolve →',`data-audit-resolve="${esc(x.key)}"`,'button small primary')}</div>`).join('')||'<div class="callout good"><strong>✓ Current evidence checks are ready.</strong></div>'}</div></div><details class="card fold"><summary>✓ Ready controls (${ready.length})</summary><div class="table-wrap"><table class="data-table"><tbody>${ready.map(x=>`<tr><td>${esc(x.clause)}</td><td><strong>${esc(x.title)}</strong></td><td>${esc(x.evidence)}</td></tr>`).join('')}</tbody></table></div></details><details class="card fold"><summary>Laboratory capability scope (${scope.length})</summary><div class="table-wrap"><table class="data-table lab-scope-table"><thead><tr><th>Equipment</th><th>Activity</th><th>Range</th><th>Resolution</th><th>Uncertainty / capability</th><th>Method</th><th></th></tr></thead><tbody>${scope.map(x=>`<tr><td><strong>${esc(x.id)} · ${esc(x.name)}</strong></td><td>${esc(x.activity||'MISSING')}</td><td>${esc(x.range||'MISSING')}</td><td>${esc(x.resolution||'—')}</td><td>${esc(x.uncertainty||'—')}</td><td>${esc(x.method||'MISSING')}</td><td>${(currentRole()==='administrator'||can('equipment:manage'))?btn('Edit',`data-edit-equipment-scope="${x.id}"`,'button tiny secondary'):''}</td></tr>`).join('')}</tbody></table></div></details><details class="card fold"><summary>Exports & audit documents</summary><div class="route-toolbar">${btn('Findings CSV','data-audit-export-findings','button secondary')}${btn('Lab scope CSV','data-audit-export-scope','button secondary')}${btn('Print evidence pack','data-audit-pack','button primary')}</div></details>`}
function renderAdmin(){const inv=P.validateInvariants(App.state),open=openActions().length,customers=App.state.customers||[];return pageHeader('Configuration & data','Master data and system administration.')+`<div class="card"><div class="section-title-row"><div><span class="eyebrow">CUSTOMERS & REQUIREMENTS</span><h2>${customers.length} customer profile${customers.length===1?'':'s'}</h2></div>${btn('+ Add customer','data-add-customer','button small primary')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Retention</th><th>Required approvals</th><th></th></tr></thead><tbody>${customers.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.retention||'—')}</td><td>${esc((c.requiredApprovals||[]).join(', ')||'Standard')}</td><td>${btn('Edit',`data-edit-customer="${c.id}"`,'button tiny secondary')}</td></tr>`).join('')||'<tr><td colspan="4">No customer profiles yet.</td></tr>'}</tbody></table></div></div><details class="card fold"><summary>Data management</summary><div class="route-toolbar">${btn('Export JSON','data-export','button primary')}${btn('Import validated JSON','data-import','button secondary')}${btn('Reset demo data','data-reset','button danger')}</div></details><details class="card fold"><summary>System status · REV ${esc(P.VERSION.replace('-poc',''))}</summary><div class="score-row"><span>Schema</span><strong>${esc(App.state.schemaVersion)}</strong></div><div class="score-row"><span>Requests / routes / samples</span><strong>${App.state.requests.length} / ${App.state.routes.length} / ${App.state.serials.length}</strong></div><div class="score-row"><span>Open actions</span><strong>${open}</strong></div><div class="score-row"><span>Invariant validation</span><strong class="${inv.length?'bad-text':'good-text'}">${inv.length?`${inv.length} issue(s)`:'✓ Clean'}</strong></div>${inv.length?`<details><summary>Integrity issues</summary>${inv.map(x=>`<div class="callout bad"><p>${esc(x)}</p></div>`).join('')}</details>`:''}</details>`}
function render(){const p=$('#page');let html='';switch(App.currentView){case'dashboard':html=renderDashboard();break;case'requests':html=renderRequests();break;case'action-centre':html=renderActionCentre();break;case'workspace':html=renderWorkspace();break;case'planning':html=renderPlanning();break;case'products':html=renderProducts();break;case'process-library':html=renderProcessLibrary();break;case'equipment-master':html=renderEquipmentMaster();break;case'serials':html=renderSerials();break;case'characterisation':html=renderCharacterisation();break;case'quality':html=renderQuality();break;case'reports':html=renderReports();break;case'management':html=renderManagement();break;case'audit-readiness':html=renderAuditReadiness();break;case'admin':html=renderAdmin();break;case'help':html=renderHelp();break;default:html=renderDashboard()}p.innerHTML=html;bindDynamic();if(App.currentView==='workspace')scheduleWorkspaceCockpitLayout();else document.documentElement?.style?.removeProperty('--workspace-cockpit-height')}

function pipelineProjectModal(id=null){const existing=id?(App.state.pipelineProjects||[]).find(x=>x.id===id):null,p=existing||{name:'',productId:App.state.products[0]?.id,quantity:5,probability:.5,startDate:new Date(Date.now()+30*86400000).toISOString().slice(0,10),owner:App.state.identity.name,estimatedCost:0};if(!p.estimatedCost)p.estimatedCost=P.pipelineProjectCost(App.state,p);openModal(existing?'Edit potential project':'Add potential project',`<div class="callout"><h3>Scenario only</h3><p>Potential projects carry both probability-weighted capacity demand and an estimated project cost. The cost may be overridden if commercial knowledge is better than the automatic BOM/process estimate.</p></div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>Project / opportunity name</label><input id="pipeName" value="${esc(p.name)}"></div><div class="field"><label>Product</label><select id="pipeProduct">${App.state.products.map(x=>`<option value="${x.id}" ${p.productId===x.id?'selected':''}>${esc(x.family)}</option>`).join('')}</select></div><div class="field"><label>Quantity</label><input id="pipeQty" type="number" min="1" value="${Number(p.quantity||1)}"></div><div class="field"><label>Probability %</label><input id="pipeProb" type="number" min="1" max="100" value="${Math.round(Number(p.probability||0)*100)}"></div><div class="field"><label>Expected start</label><input id="pipeStart" type="date" value="${esc(p.startDate)}"></div><div class="field"><label>Estimated project cost (€)</label><input id="pipeCost" type="number" min="0" step="1" value="${Number(p.estimatedCost||0).toFixed(0)}"></div><div class="field full"><label>Owner / source</label><input id="pipeOwner" value="${esc(p.owner||'')}"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn(existing?'Save project':'Add project','data-save-pipeline','button primary')}`);setTimeout(()=>{$('[data-save-pipeline]').onclick=async()=>{const name=$('#pipeName').value.trim(),qty=Number($('#pipeQty').value),prob=Math.max(.01,Math.min(1,Number($('#pipeProb').value)/100)),start=$('#pipeStart').value;if(!name||qty<1||!start){toast('Name, quantity and expected start are required.',true);return}const obj=existing||{id:P.uid('PIPE')};Object.assign(obj,{name,productId:$('#pipeProduct').value,quantity:qty,probability:prob,startDate:start,owner:$('#pipeOwner').value.trim()||App.state.identity.name});const entered=Number($('#pipeCost').value||0),auto=P.pipelineProjectCost(App.state,obj);obj.estimatedCost=entered>0?entered:Number(auto.toFixed(2));obj.costSource=entered>0?'manual':'auto';if(!existing)(App.state.pipelineProjects||(App.state.pipelineProjects=[])).push(obj);P.audit(App.state,existing?'Potential project updated':'Potential project added','Pipeline Project',obj.id,existing?'Previous scenario':'—',`${name} · ${Math.round(prob*100)}% · ${P.currency(obj.estimatedCost)}`,start);await persist();closeModal();render();toast('Potential project scenario and cost saved.')}},0)}
function pipelineImpactModal(id){const x=futureProjectImpact(id);if(!x)return;const p=x.project,max=Math.max(1,...x.resources.map(r=>r.hours));openModal(`Scenario impact · ${p.name}`,`<div class="grid cols-4"><div class="mini-kpi"><span>Estimated project cost</span><strong>${P.currency(p.estimatedCost||P.pipelineProjectCost(App.state,p))}</strong></div><div class="mini-kpi"><span>Baseline peak load</span><strong>${x.basePeak.toFixed(0)}%</strong></div><div class="mini-kpi"><span>With probability weighting</span><strong>${x.weightedPeak.toFixed(0)}%</strong><small>${x.weightedDelta>=0?'+':''}${x.weightedDelta.toFixed(0)} pp</small></div><div class="mini-kpi"><span>If project wins (100%)</span><strong>${x.fullPeak.toFixed(0)}%</strong><small>${x.fullDelta>=0?'+':''}${x.fullDelta.toFixed(0)} pp</small></div></div><div class="callout ${x.fullPeak>100?'warn':''}" style="margin-top:12px"><h3>${x.fullPeak>100?'Capacity action would be required if this project wins':'Current lab capacity can absorb this project in the modeled horizon'}</h3><p><strong>${Math.round(p.probability*100)}% probability</strong> · ${p.quantity} units · expected ${P.formatDate(p.startDate)} · probability-weighted equipment demand contribution ${x.weightedHours.toFixed(1)} h.</p></div><div class="card flat" style="margin-top:12px"><div class="section-title-row"><div><span class="eyebrow">INDIVIDUAL RESOURCE IMPACT</span><h3>What this project adds</h3></div></div><div class="ops-load-bars">${x.resources.slice(0,10).map(r=>`<div class="ops-load-row"><div><strong>${esc(r.label)}</strong><small>${esc(r.type)}</small></div><div class="ops-load-track"><span style="width:${100*r.hours/max}%"></span></div><b>${r.hours.toFixed(1)} h</b></div>`).join('')||'<div class="empty compact">No modeled resource demand.</div>'}</div></div>`,`${btn('Close','data-modal-close','button')}${btn('Edit project','data-edit-pipeline-from-impact','button secondary')}`,true);setTimeout(()=>{const e=$('[data-edit-pipeline-from-impact]');if(e)e.onclick=()=>{closeModal();pipelineProjectModal(id)}},0)}

async function removePipelineProject(id){const x=(App.state.pipelineProjects||[]).find(p=>p.id===id);if(!x)return;if(!confirm(`Remove potential project scenario “${x.name}”?`))return;App.state.pipelineProjects=App.state.pipelineProjects.filter(p=>p.id!==id);P.audit(App.state,'Potential project removed','Pipeline Project',id,x.name,'Removed','Scenario only; no committed bookings changed');await persist();render();toast('Potential project removed.')}
