function showStep(id){const route=App.state.routes.find(r=>r.requestId===App.workspaceId),s=route.steps.find(x=>x.id===id),p=App.state.processes.find(x=>x.id===s.processId),dev=App.state.processDevelopments.find(x=>x.requestId===App.workspaceId&&(x.libraryCandidate===s.processId||x.name.includes(s.name)));openModal(`${s.name} · Step ${s.order}`,`<div class="grid cols-2"><div class="card"><h3>Controlled step</h3><div class="score-row"><span>Type</span><strong>${esc(s.type)}</strong></div><div class="score-row"><span>Process revision</span><strong>${esc(s.processRevision)}</strong></div><div class="score-row"><span>Owner</span><strong>${esc(s.owner)}</strong></div><div class="score-row"><span>Planned</span><strong>${P.formatDateTime(s.planned)}</strong></div><div class="score-row"><span>Status</span>${status(s.status)}</div></div><div class="card"><h3>Requirements</h3>${(p?.requiredEvidence||['Controlled evidence']).map(x=>`<div class="score-row"><span>${esc(x)}</span><span class="warnmark">○</span></div>`).join('')}</div></div>${dev?`<div style="height:12px"></div><div class="callout warn"><h3>${esc(dev.conclusion)}</h3><p>Development ${esc(dev.id)} · ${esc(dev.status)}. Complete development gates before this process can be released for controlled execution.</p></div>`:''}`,btn('Close','data-modal-close','button'),true)}
async function requestControlPlanReview(id){const cp=App.state.controlPlans.find(x=>x.id===id);if(!cp){toast('Control Plan not found.',true);return}if(!(can('controlplan:edit')||currentRole()==='administrator')){toast('Current role cannot submit Control Plans for review.',true);return}const invalid=(cp.characteristics||[]).filter(c=>c.classification&&!P.controlCharacteristicReady(c));if(invalid.length){toast('Complete all controlled characteristic definitions before requesting review.',true);return}if(cp.status!=='Draft'){toast(`Control Plan is already ${cp.status}.`,cp.status!=='Review requested');return}const prev=cp.status;cp.status='Review requested';cp.reviewRequestedAt=P.now();cp.reviewRequestedBy=App.state.identity.name;P.audit(App.state,'Control Plan review requested','Control Plan',id,prev,cp.status,`Independent approval requested by ${App.state.identity.name}`);await persist();render();toast('Control Plan submitted for independent review.')}
async function approveCp(id){const cp=App.state.controlPlans.find(x=>x.id===id);if(!cp){toast('Control Plan not found.',true);return}const ap=controlPlanApprovalState(cp);if(!ap.canApprove){toast(ap.reason,true);return}try{new P.ControlPlanService(App.state).approve(id);const r=cp.buildSpecific?requestById(cp.buildRequestId):null;if(r){const pack=P.ensureReusePackage(r);if(pack.controlPlan){pack.controlPlan.mode='modified';pack.controlPlan.buildSpecificId=cp.id;pack.controlPlan.approvedRevision=cp.revision;pack.controlPlan.approvedAt=cp.approvedAt}P.ensureApprovalRecords(App.state,r)}await persist();render();toast(`Control Plan ${cp.id} Rev ${cp.revision} formally approved by ${App.state.identity.name}.`)}catch(e){toast(e.message,true)}}
async function approveRecord(id){const a=App.state.approvals.find(x=>x.id===id);if(!a){toast('Approval record not found.',true);return}if(!canApproveRecord(a)){toast(`This approval requires ${a.role}.`,true);return}if(a.status==='Approved'){toast('Approval is already complete.');return}const prev=a.status;a.status='Approved';a.person=App.state.identity.name;a.timestamp=P.now();a.comment=a.comment&&a.comment!=='Pending'?a.comment:'Approved in controlled workflow';if(a.stage==='build-change'){const r=requestById(a.requestId);if(r&&P.buildChangeApprovalsComplete(App.state,r,a.changeArea)){const pack=P.ensureReusePackage(r);(pack.deltas||[]).filter(d=>d.area===a.changeArea&&d.status==='Open').forEach(d=>{d.status='Reviewed';d.reviewedAt=P.now()})}}P.audit(App.state,'Approval completed','Approval',a.id,prev,'Approved',`${a.type} · ${App.state.identity.name}`);await persist();render();toast(`${a.type} approval recorded.`)}
function controlPlanDefinitionResolver(cpId){const cp=App.state.controlPlans.find(c=>c.id===cpId);if(!cp){toast('Control Plan not found.',true);return}const invalid=(cp.characteristics||[]).filter(c=>c.classification&&!P.controlCharacteristicReady(c));if(!invalid.length){toast('Controlled definition is complete. Formal approval can now proceed.');render();return}const c=invalid[0];toast(`${invalid.length} controlled definition item${invalid.length===1?'':'s'} remaining. Opening ${c.characteristic||c.id}.`);editCpCharacteristic(cp.id,c.id)}
