function createControlPlan(requestId){const r=requestById(requestId),route=App.state.routes.find(x=>x.requestId===requestId);const chars=(r.specialCharacteristics||[]).map((sc,i)=>({id:`${sc}-${i+1}`,processStep:route?.steps[Math.min(i,Math.max(0,(route?.steps.length||1)-1))]?.order||1,characteristic:sc,classification:'SC',target:'Define target',lsl:null,usl:null,unit:'',method:'',equipment:'',sampleSize:'100%',frequency:'Each unit',controlMethod:'To be defined',role:'Quality / Technician',reactionPlan:'Hold affected serial; notify Quality; disposition before release',evidence:'Guided build result'}));if(!chars.length)chars.push({id:P.uid('CHAR'),processStep:route?.steps[0]?.order||1,characteristic:'Prototype functional acceptance',classification:'',target:'Pass',lsl:null,usl:null,unit:'',method:'Functional verification',equipment:'Applicable released equipment',sampleSize:'100%',frequency:'Each unit',controlMethod:'Recorded pass/fail',role:'Technician',reactionPlan:'Hold on failure; open deviation',evidence:'Guided build result'});const cp={id:P.uid('CP'),name:`${r.productFamily} Prototype Control Plan`,revision:'A',phase:'Prototype',status:'Draft',owner:App.state.identity.name,approvedBy:null,approvedAt:null,requestIds:[requestId],characteristics:chars};App.state.controlPlans.push(cp);r.controlPlanId=cp.id;P.audit(App.state,'Control Plan created','Control Plan',cp.id,'—','Draft',`Linked to ${requestId}`);persist().then(()=>{render();toast('Draft Control Plan created and linked to request.')})}
function advanceGateModal(id){
 const r=requestById(id);if(!r){toast('Request not found.',true);return}const lifecycle=new P.LifecycleService(App.state),check=lifecycle.check(id);if(!check.next){toast(check.blockers?.[0]||'No later gate is available.',true);return}if(!check.ok){toast(check.blockers.join(' '),true);return}
 openModal(`Gate review · ${r.currentGate} → ${check.next}`,`<div class="callout"><h3>Objective gate review</h3><p>The same lifecycle rules are enforced in the domain service and in this interface. A hidden button, direct service call or imported state cannot bypass the gate-specific execution, quality or release checks.</p></div><div style="height:12px"></div><div class="field"><label>Evidence / review conclusion <small>required</small></label><textarea id="gateEvidence" placeholder="What evidence was reviewed and what conclusion was reached?"></textarea></div><div class="field" style="margin-top:12px"><label>Reason / decision note</label><input id="gateReason" placeholder="Controlled decision note"></div>`,`${btn('Cancel','data-modal-close','button')}${btn(`Advance to ${check.next}`,`data-confirm-gate="${id}"`,'button primary')}`);setTimeout(()=>{$('[data-confirm-gate]').onclick=async()=>{const evidence=$('#gateEvidence').value.trim(),reason=$('#gateReason').value.trim();try{new P.LifecycleService(App.state).advance(id,{evidence,reason});await persist();closeModal();render();toast(`Gate advanced to ${r.currentGate}.`)}catch(e){toast(e.message,true)}}},0)
}
