 openModal(`Implement improvement · ${x.type||'Operational'}`,`<div class="implementation-head"><span class="eyebrow">ACCEPTED · IMPLEMENTATION IN PROGRESS</span><h2>${esc(a.title)}</h2><p>${esc(impl.guidanceReason||'LabOS cannot truthfully mark this physical/governed action complete automatically, so it guides each required step and updates the controlled records as those steps are completed.')}</p></div><div class="implementation-rail">${steps.map((st,i)=>`<div class="${i<cur?'complete':i===cur?'current':''}"><span>${i<cur?'✓':i+1}</span><div><strong>${esc(st[0])}</strong><small>${esc(st[1])}</small>${impl.stepEvidence?.[i]?`<em>${esc(impl.stepEvidence[i])}</em>`:''}</div></div>`).join('')}</div><div class="callout"><strong>Current step · ${cur+1}/${steps.length}: ${esc(steps[cur][0])}</strong><p>${esc(steps[cur][1])}</p></div>${special}<div class="field"><label>Step evidence / decision</label><textarea id="impStepEvidence" placeholder="Record the controlled evidence for this step."></textarea></div>`,`${btn('Close','data-modal-close','button')}${btn(target.label,`data-implementation-open="${esc(target.view)}"`,'button secondary')}${btn(cur===steps.length-1?'Complete implementation & verify':'Complete this step →',`data-implementation-next="${esc(a.id)}"`,'button primary')}`,true);
