function improvementDecisionModal(id,decision){const service=new P.ImprovementService(),x=(App.state.improvementProposals||service.generate(App.state)).find(p=>p.id===id)||latestImprovementDecision(id)?.snapshot;if(!x){toast('Improvement proposal is no longer active.',true);return}const defaultDate=new Date(Date.now()+(decision==='Deferred'?7:14)*86400000).toISOString().slice(0,10),label=decision==='Accepted'?'Accept & implement':decision==='Rejected'?'Reject / not applicable':'Defer review';openModal(`${label} · ${x.type}`,`<div class="callout ${decision==='Rejected'?'bad':'warn'}"><h3>${esc(x.title)}</h3><p>${esc(x.why)}</p></div><div class="score-row"><span>Proposed action</span><strong>${esc(x.proposal)}</strong></div><div class="score-row"><span>Expected impact</span><strong>${esc(x.impact)}</strong></div>${decision==='Accepted'?'<div class="callout"><strong>Accept means implement.</strong><p>LabOS will immediately apply safe deterministic changes (for example qualified staff/equipment rebalancing or a low-impact service booking). If the change requires a physical/governed action, it will open the exact guided implementation workflow and keep it open until completed.</p></div>':''}<div class="form-grid" style="margin-top:12px"><div class="field"><label>${decision==='Accepted'?'Implementation owner':'Decision owner'}</label><input id="impOwner" value="${esc(x.owner||App.state.identity.name)}"></div><div class="field"><label>${decision==='Deferred'?'Review again':'Target / review date'}</label><input id="impDue" type="date" value="${defaultDate}"></div><div class="field full"><label>Decision rationale / evidence</label><textarea id="impNote" placeholder="Why is this decision appropriate?"></textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn(label,`data-save-improvement-decision="${esc(id)}|${decision}"`,'button primary')}`,true);setTimeout(()=>{$('[data-save-improvement-decision]').onclick=async()=>{const note=$('#impNote').value.trim(),owner=$('#impOwner').value.trim()||x.owner||App.state.identity.name,due=$('#impDue').value;if(!note){toast('Record the decision rationale before continuing.',true);return}App.state.improvementDecisions=App.state.improvementDecisions||[];const rec={id:P.uid('IMPD'),proposalId:id,decision,at:P.now(),actor:App.state.identity.name,owner,note,reviewAfter:due||null,snapshot:P.deepClone(x)};App.state.improvementDecisions.push(rec);let action=null,apply=null;if(decision==='Accepted'){App.state.actions=App.state.actions||[];action=App.state.actions.find(a=>a.improvementProposalId===id);if(!action){action={id:P.uid('ACT'),requestId:null,category:`Improvement · ${x.type}`,title:x.title,why:x.why,impact:x.impact,owner,due:due||defaultDate,severity:x.severity==='High'?'bad':'warn',resolve:improvementResolveTarget(x),note,improvementProposalId:id};App.state.actions.push(action)}apply=service.implementAccepted(App.state,x);action.implementation=apply.mode==='automatic'?{status:'Applied · verification pending',currentStep:99,startedAt:P.now(),startedBy:App.state.identity.name,appliedAt:P.now(),appliedBy:App.state.identity.name,automaticSummary:apply.summary,appliedChanges:apply.changes||[],workflowKind:apply.kind}:{status:'In progress',currentStep:0,startedAt:P.now(),startedBy:App.state.identity.name,stepEvidence:[],workflowKind:apply.kind||x.type.toLowerCase(),guidanceReason:apply.reason||'Controlled implementation is required.',capability:apply.capability||null,equipmentId:apply.equipmentId||x.equipmentId||null};}P.audit(App.state,`Improvement proposal ${decision.toLowerCase()}`,'Improvement',id,'Proposed',decision,`${note} · owner ${owner}${apply?` · ${apply.mode}`:''}`);service.generate(App.state);await persist();closeModal();render();if(decision==='Accepted'){toast(apply?.mode==='automatic'?'Accepted change applied to LabOS. Verify effectiveness to close it.':'Accepted. Guided implementation has started.');setTimeout(()=>improvementImplementationModal(action.id),0)}else toast(decision==='Rejected'?'Improvement rejected with rationale retained.':'Improvement deferred; review date retained.')}},0)}
function improvementModal(id){const x=(App.state.improvementProposals||new P.ImprovementService().generate(App.state)).find(p=>p.id===id)||latestImprovementDecision(id)?.snapshot;if(!x)return;const d=latestImprovementDecision(id),action=(App.state.actions||[]).find(a=>a.improvementProposalId===id),decisionBlock=d?`<div class="callout"><strong>Latest decision: ${esc(d.decision)}</strong><p>${P.formatDateTime(d.at)} · ${esc(d.actor||'')} · ${esc(d.note||'')}</p>${action?.implementation?`<p><strong>Implementation:</strong> ${esc(action.implementation.status||'In progress')}</p>`:''}</div>`:'';openModal(`Improvement proposal · ${x.type}`,`${decisionBlock}<div class="callout warn"><h3>${esc(x.title)}</h3><p>${esc(x.why)}</p></div><div class="score-row"><span>Proposed action</span><strong>${esc(x.proposal)}</strong></div><div class="score-row"><span>Expected impact</span><strong>${esc(x.impact)}</strong></div><div class="score-row"><span>Owner</span><strong>${esc(x.owner)}</strong></div>`,`${btn('Close','data-modal-close','button')}${d?.decision==='Accepted'&&action?btn('Continue / verify implementation',`data-implementation-review="${action.id}"`,'button primary'):d?'':`${btn('Reject',`data-improvement-decision="${esc(id)}|Rejected"`,'button danger')}${btn('Defer',`data-improvement-decision="${esc(id)}|Deferred"`,'button secondary')}${btn('Accept & implement',`data-improvement-decision="${esc(id)}|Accepted"`,'button primary')}`}`);setTimeout(()=>{$$('[data-implementation-review]').forEach(b=>b.onclick=()=>{closeModal();improvementImplementationModal(b.dataset.implementationReview)})},0)}
